/**
 *
 * DatePickerBody is the outer wrapper that lays panels side-by-side (multi-month).
 * Used inside the popup OR directly under the root in inline mode.
 *
 * [Live Demo](https://www.primereact.org/datepicker/)
 *
 * @module DatePickerBody
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DatePickerRootInstance } from './DatePickerRoot.types';
/**
 * Defines passthrough(pt) options type in DatePickerBody component.
 */
export type DatePickerBodyPassThroughType<E> = PassThroughType<DatePickerBodyInstance, E>;
/**
 * Defines passthrough(pt) options of DatePickerBody component.
 */
export interface DatePickerBodyPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DatePickerBodyPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in DatePickerBody component.
 */
export interface DatePickerBodyProps extends BaseComponentProps<DatePickerBodyInstance, unknown, DatePickerBodyPassThrough> {
}
/**
 * Defines valid state in DatePickerBody component.
 */
export interface DatePickerBodyState {
}
/**
 * Defines the methods and properties exposed by DatePickerBody component.
 */
export interface DatePickerBodyExposes {
    /**
     * Instance of the DatePicker component.
     */
    datepicker: DatePickerRootInstance | undefined | null;
}
/**
 * Instance of DatePickerBody component.
 */
export type DatePickerBodyInstance = ComponentInstance<DatePickerBodyProps, DatePickerBodyState, DatePickerBodyExposes>;
